655	/** Fill in any fields added in recent STATE_VERSIONs without wiping existing data. */
656	export function migrateToCurrentVersion(parsed: HermesState): HermesState {
657	  const defs = defaultSettings();
658	  // STATE_VERSION 12 — the demo moved to Kimi (Kimi Code) via the server env key.
659	  // Blobs older than 12 have their model layer reset below so returning visitors
660	  // leave the previous Anthropic default (which would fall back to the mock).
661	  const preKimi = (parsed.version ?? 0) < 12;
662	  const starT = parsed.settings?.starRatingThresholds ?? DEFAULT_STAR_THRESHOLDS;
663	  return {
664	    ...parsed,
665	    version: STATE_VERSION,
666	    // D-2: fill every required root field that may be absent in older blobs.
667	    campaigns: parsed.campaigns ?? [],
668	    // STATE_VERSION 13 — backfill the TAnIA layer (lead source + star rating) on
669	    // any candidate that predates it, without clobbering explicit values.
670	    candidates: (parsed.candidates ?? []).map((c) => ({
671	      ...c,
672	      leadSource: c.leadSource ?? deriveLeadSource(c),
673	      starRating: c.starRating ?? deriveStarRating(c.matchScore, starT),
674	    })),
675	    // STATE_VERSION 13 — inbound chatbox queue.
676	    chatboxSubmissions: parsed.chatboxSubmissions ?? [],
677	    outreach: parsed.outreach ?? [],
678	    replies: parsed.replies ?? [],
679	    bookings: parsed.bookings ?? [],
680	    reports: parsed.reports ?? [],
681	    // STATE_VERSION 16 — re-sync each stored integration's `real` flag against
682	    // the current seed. Roadmap placeholders (`real: false`) also lose any older
683	    // fabricated connected/lastSync state; real cards keep their usage history.
684	    integrations:
685	      parsed.integrations && parsed.integrations.length > 0
686	        ? parsed.integrations.map((i) => {
687	            const seed = defaultIntegrations().find((d) => d.id === i.id);
688	            if (!seed) return i;
689	            return seed.real ? { ...i, real: true } : { ...i, real: false, status: "not_configured", lastSync: null };
690	          })
691	        : defaultIntegrations(),
692	    activities: parsed.activities ?? [],
693	    activeCampaignId: parsed.activeCampaignId ?? null,
694	    apiKeys: parsed.apiKeys ?? [],
695	    currentRole: parsed.currentRole ?? "admin",
696	    skills: parsed.skills ?? [],
697	    suppression: parsed.suppression ?? [],
698	    ledger: parsed.ledger ?? [],
