188	                            {lastEvent && (
189	                              <p className="mt-1 truncate text-xs text-ink-soft">
190	                                {KIND_LABEL[lastEvent.kind]}: {lastEvent.label}
191	                              </p>
192	                            )}
193	                          </div>
194	                        </div>
195	                      </div>
196	                    );
197	                  })}
198	                </div>
199	              )}
200	            </div>
201	          </div>
202	        )}
203	      </HydrationGate>
204	    </div>
205	  );
206	}

