 11	/* ============================================================================
 12	   Mission Control HUD — a glass overlay floating over the 3D floor canvas
 13	   (mounted only in the 3D view from src/app/floor/page.tsx; the existing
 14	   ActivityTicker stays the guaranteed 2D/low-tier fallback).
 15	
 16	   Every tile is a live read of the REAL store — never a theatrical
 17	   incrementer:
 18	     Sourced   = candidates.length                    (useCandidates)
 19	     Contacted = ledger entries with status "sent"     (useLedger)
 20	     Drafted   = outreach messages ever generated      (useOutreach)
 21	     Approved  = outreach messages with approvedBy set (useOutreach)
 22	     Booked    = booking records                       (useBookings)
 23	   `useCountUp` (src/components/reveal/use-count-up.ts) animates old -> new
 24	   whenever a real value changes. The agent-events bus only decides *when* to
 25	   re-check for a delta (within one tick of the emitting store action, same
 26	   guarantee as the 1.2 floor FX) and feeds the throughput sparkline — it
 27	   never supplies the numbers themselves, so the HUD can never drift from
 28	   true state.
 29	   ========================================================================== */
 30	
 31	type TileKey = "sourced" | "contacted" | "drafted" | "approved" | "booked";
 32	
 33	const TILE_ORDER: TileKey[] = ["sourced", "contacted", "drafted", "approved", "booked"];
 34	
 35	const TILE_META: Record<TileKey, { label: string; icon: React.ReactNode; varName: string }> = {
 36	  sourced: { label: "Sourced", icon: <Users className="h-3 w-3" aria-hidden />, varName: "--electric" },
 37	  contacted: { label: "Contacted", icon: <Mail className="h-3 w-3" aria-hidden />, varName: "--tangerine" },
 38	  drafted: { label: "Drafted", icon: <PenLine className="h-3 w-3" aria-hidden />, varName: "--violet" },
 39	  approved: { label: "Approved", icon: <CheckCircle2 className="h-3 w-3" aria-hidden />, varName: "--success" },
 40	  booked: { label: "Booked", icon: <CalendarCheck className="h-3 w-3" aria-hidden />, varName: "--aqua" },
 41	};
 42	
 43	type Flash = { until: number; delta: number };
 44	
 45	const FLASH_MS = 1400;
 46	const SPARK_BUCKET_MS = 4000;
 47	const SPARK_BUCKET_COUNT = 16; // ~64s rolling window
 48	
 49	function usePrefersReducedMotion(): boolean {
 50	  const [reduced, setReduced] = React.useState(false);
 51	  React.useEffect(() => {
 52	    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
 53	    setReduced(mq.matches);
 54	    const onChange = () => setReduced(mq.matches);
 55	    mq.addEventListener("change", onChange);
 56	    return () => mq.removeEventListener("change", onChange);
 57	  }, []);
 58	  return reduced;
 59	}
 60	
 61	function bucketEvents(events: AgentEvent[], now: number): number[] {
 62	  const buckets = new Array(SPARK_BUCKET_COUNT).fill(0) as number[];
 63	  const windowMs = SPARK_BUCKET_COUNT * SPARK_BUCKET_MS;
 64	  for (const e of events) {
 65	    const age = now - e.at;
 66	    if (age < 0 || age >= windowMs) continue;
 67	    const idx = SPARK_BUCKET_COUNT - 1 - Math.floor(age / SPARK_BUCKET_MS);
 68	    if (idx >= 0 && idx < SPARK_BUCKET_COUNT) buckets[idx] += 1;
 69	  }
 70	  return buckets;
 71	}
 72	
 73	export function MissionControlHud() {
 74	  const candidates = useCandidates();
 75	  const ledger = useLedger();
 76	  const outreach = useOutreach();
 77	  const bookings = useBookings();
 78	  const reducedMotion = usePrefersReducedMotion();
 79	
 80	  const values: Record<TileKey, number> = {
 81	    sourced: candidates.length,
 82	    contacted: ledger.filter((l) => l.status === "sent").length,
 83	    drafted: outreach.length,
 84	    approved: outreach.filter((m) => m.approvedBy != null).length,
 85	    booked: bookings.length,
 86	  };
 87	
 88	  // Always-fresh mirror of the real values, read from inside callbacks below
 89	  // without re-subscribing them to every render.
 90	  const valuesRef = React.useRef(values);
 91	  valuesRef.current = values;
 92	  const lastSeenRef = React.useRef(values);
 93	  const [flashes, setFlashes] = React.useState<Partial<Record<TileKey, Flash>>>({});
 94	
 95	  const checkDeltas = React.useCallback(() => {
 96	    const latest = valuesRef.current;
 97	    const prev = lastSeenRef.current;
 98	    const until = Date.now() + FLASH_MS;
 99	    let changed: Partial<Record<TileKey, Flash>> | null = null;
100	    for (const key of TILE_ORDER) {
101	      const delta = latest[key] - prev[key];
102	      if (delta !== 0) {
103	        changed ??= {};
104	        changed[key] = { until, delta };
105	      }
106	    }
107	    if (changed) {
108	      lastSeenRef.current = latest;
109	      setFlashes((old) => ({ ...old, ...changed }));
110	    }
111	  }, []);
112	
113	  // Real state changed -> flash + count-up. Fires even if the bus is silent
114	  // for some reason, so the scoreboard can never silently go stale.
115	  React.useEffect(() => {
116	    checkDeltas();
117	    // eslint-disable-next-line react-hooks/exhaustive-deps
118	  }, [values.sourced, values.contacted, values.drafted, values.approved, values.booked]);
119	
120	  // Agent-events bus: re-check within one tick of the emitting action (same
121	  // guarantee 1.1/1.2 rely on), and feed the throughput sparkline — raw event
122	  // kinds/timestamps aren't reconstructable from any store selector.
123	  const [sparkBuckets, setSparkBuckets] = React.useState<number[]>(() =>
124	    bucketEvents(recentEvents(), Date.now()),
125	  );
126	  React.useEffect(() => {
127	    const unsubscribe = subscribe(() => {
128	      checkDeltas();
129	      setSparkBuckets(bucketEvents(recentEvents(), Date.now()));
130	    });
131	    const id = setInterval(() => {
132	      setSparkBuckets(bucketEvents(recentEvents(), Date.now()));
133	    }, 2000);
134	    return () => {
135	      unsubscribe();
136	      clearInterval(id);
137	    };
138	  }, [checkDeltas]);
139	
140	  // Let expired flashes drop off on a slow tick (DOM overlay — no need for
141	  // per-frame precision here, unlike the 3D FX layer).
142	  const [, forceTick] = React.useReducer((n: number) => n + 1, 0);
143	  React.useEffect(() => {
144	    const id = setInterval(forceTick, 400);
145	    return () => clearInterval(id);
146	  }, []);
147	
148	  const now = Date.now();
149	
150	  return (
151	    <div className="pointer-events-none absolute inset-0 z-10 select-none">
152	      <div
153	        role="group"
154	        aria-label="Mission control scoreboard, live counts"
155	        className="pointer-events-none absolute left-3 right-3 top-3 flex flex-wrap gap-2 sm:right-auto"
156	      >
157	        {TILE_ORDER.map((key) => (
158	          <HudTile
159	            key={key}
160	            tileKey={key}
161	            value={values[key]}
162	            flash={flashes[key]}
163	            now={now}
164	            reducedMotion={reducedMotion}
165	          />
166	        ))}
167	      </div>
168	      <div className="pointer-events-auto absolute bottom-3 right-3">
169	        <ThroughputSparkline buckets={sparkBuckets} />
170	      </div>
171	    </div>
172	  );
173	}
174	
175	function HudTile({
176	  tileKey,
177	  value,
178	  flash,
179	  now,
180	  reducedMotion,
181	}: {
182	  tileKey: TileKey;
183	  value: number;
184	  flash: Flash | undefined;
185	  now: number;
186	  reducedMotion: boolean;
187	}) {
188	  const meta = TILE_META[tileKey];
189	  const display = useCountUp(value, { durationMs: 700 });
190	  const flashing = !!flash && flash.until > now;
191	  const solid = `hsl(var(${meta.varName}))`;
192	  const tint = `hsl(var(${meta.varName}) / 0.16)`;
