131	/** Tolerant JSON parse + per-field validation. Returns null only when the reply
132	 *  has no usable JSON object at all — caller then falls back entirely to the
133	 *  heuristic. Mirrors parseHermesOutreach's tolerant-parse contract. */
134	export function parseHermesIntakeJson(text: string): LiveIntakeFields | null {
135	  const trimmed = (text ?? "")
136	    .trim()
137	    .replace(/^```(?:json)?\s*/i, "")
138	    .replace(/```\s*$/, "");
139	  let raw: unknown;
140	  try {
141	    raw = JSON.parse(trimmed);
142	  } catch {
143	    return null;
144	  }
145	  if (!raw || typeof raw !== "object") return null;
146	  const o = raw as Record<string, unknown>;
147	
148	  return {
149	    senderName: pickString(o.senderName),
150	    senderEmail: pickEmail(o.senderEmail),
151	    intent: pickEnum(o.intent, INTAKE_INTENTS),
152	    urgency: pickEnum(o.urgency, URGENCY_LEVELS),
153	    title: pickString(o.title),
154	    department: pickString(o.department),
155	    seniority: pickEnum(o.seniority, SENIORITY_LEVELS),
156	    employmentType: pickEnum(o.employmentType, EMPLOYMENT_TYPES),
157	    locationType: pickEnum(o.locationType, LOCATION_TYPES),
158	    regions: pickStringArray(o.regions),
159	    timezone: pickString(o.timezone),
160	    salaryMin: pickNumberOrNull(o.salaryMin),
161	    salaryMax: pickNumberOrNull(o.salaryMax),
162	    currency: pickString(o.currency),
163	    equity: pickBoolean(o.equity),
164	    requiredSkills: pickStringArray(o.requiredSkills),
165	    niceToHaveSkills: pickStringArray(o.niceToHaveSkills),
166	    minYearsExperience: pickNumberOrNull(o.minYearsExperience),
167	    maxYearsExperience: pickNumberOrNull(o.maxYearsExperience),
168	    education: pickString(o.education),
169	    industryExperience: pickStringArray(o.industryExperience),
170	    companyStageTarget: pickStringArray(o.companyStageTarget)?.filter((s): s is CompanyStage =>
171	      (COMPANY_STAGES as readonly string[]).includes(s),
172	    ),
173	    teamSize: pickString(o.teamSize),
174	    reportingTo: pickString(o.reportingTo),
175	    language: pickString(o.language),
176	  };
177	}
