181	export function deriveValidationWarnings(
182	  job: Pick<JobAnalysis, "salaryMin" | "salaryMax" | "requiredSkills" | "minYearsExperience">,
183	): ValidationWarning[] {
184	  const warnings: ValidationWarning[] = [];
185	  if (job.salaryMin == null && job.salaryMax == null)
186	    warnings.push({ field: "salary", severity: "warning", message: "No salary range provided." });
187	  if (job.requiredSkills.length < 3)
188	    warnings.push({
189	      field: "requiredSkills",
190	      severity: "critical",
191	      message: "Fewer than 3 required skills detected. JD may be vague.",
192	    });
193	  if (job.minYearsExperience == null)
194	    warnings.push({ field: "experience", severity: "warning", message: "No years-of-experience band specified." });
195	  return warnings;
