198	/**
199	 * Live intake parse. `parseEmailAndJD` (the heuristic) is computed first and is
200	 * the canonical fallback — returned unchanged whenever no cloud provider is
201	 * configured, the live call errors/fails, or the reply isn't usable JSON.
202	 * On a usable reply, only the fields the model actually supplied (validated
203	 * against the same enums/shape the heuristic returns) override the heuristic's;
204	 * anything omitted or invalid keeps the heuristic value. Never throws.
205	 */
206	export async function parseIntakeLive(
207	  settings: SystemSettings,
208	  input: { email: string; jd?: string },
209	): Promise<ParsedIntake> {
210	  const mock = parseEmailAndJD(input);
211	
212	  const aiCfg = resolveAiProvider(settings, "chat");
213	  if (!aiCfg && !(settings.hermesLiveMode && hermesAvailable(settings))) return mock;
214	
215	  const prompt = buildIntakeParsePrompt(`${input.email}\n${input.jd ?? ""}`);
216	
217	  let genInput: Parameters<typeof hermesGenerate>[0];
218	  if (aiCfg) {
219	    genInput = { task: "chat", prompt, provider: aiCfg.provider, model: aiCfg.model, apiKeyId: aiCfg.apiKeyId };
220	  } else {
221	    const chatModelId = settings.defaultModels?.chat;
222	    genInput = { task: "chat", prompt, hermesApiUrl: settings.hermesApiUrl, hermesApiKeyId: settings.hermesApiKeyId };
223	    if (chatModelId) {
224	      const modelName = (settings.savedModels ?? []).find((m) => m.id === chatModelId)?.modelName;
225	      if (modelName) genInput.model = modelName;
226	    }
227	  }
228	
229	  let result: Awaited<ReturnType<typeof hermesGenerate>>;
230	  try {
231	    result = await hermesGenerate(genInput);
232	  } catch {
233	    return mock;
234	  }
235	  if (!result.ok || !result.text) return mock;
236	
237	  const fields = parseHermesIntakeJson(result.text);
238	  if (!fields) return mock;
239	
240	  const jobFields = {
241	    title: fields.title ?? mock.jobAnalysis.title,
242	    department: fields.department ?? mock.jobAnalysis.department,
243	    seniority: fields.seniority ?? mock.jobAnalysis.seniority,
244	    employmentType: fields.employmentType ?? mock.jobAnalysis.employmentType,
245	    locationType: fields.locationType ?? mock.jobAnalysis.locationType,
246	    regions: fields.regions?.length ? fields.regions : mock.jobAnalysis.regions,
247	    timezone: fields.timezone ?? mock.jobAnalysis.timezone,
248	    salaryMin: fields.salaryMin !== undefined ? fields.salaryMin : mock.jobAnalysis.salaryMin,
249	    salaryMax: fields.salaryMax !== undefined ? fields.salaryMax : mock.jobAnalysis.salaryMax,
250	    currency: fields.currency ?? mock.jobAnalysis.currency,
251	    equity: fields.equity ?? mock.jobAnalysis.equity,
252	    requiredSkills: fields.requiredSkills?.length ? fields.requiredSkills : mock.jobAnalysis.requiredSkills,
253	    niceToHaveSkills: fields.niceToHaveSkills ?? mock.jobAnalysis.niceToHaveSkills,
254	    minYearsExperience:
255	      fields.minYearsExperience !== undefined ? fields.minYearsExperience : mock.jobAnalysis.minYearsExperience,
256	    maxYearsExperience:
257	      fields.maxYearsExperience !== undefined ? fields.maxYearsExperience : mock.jobAnalysis.maxYearsExperience,
258	    education: fields.education ?? mock.jobAnalysis.education,
259	    industryExperience: fields.industryExperience ?? mock.jobAnalysis.industryExperience,
260	    companyStageTarget: fields.companyStageTarget?.length ? fields.companyStageTarget : mock.jobAnalysis.companyStageTarget,
220	 *  false positive here would parse a random email into a job brief. */
221	export function isNeedEmail(subject: string, body: string): boolean {
222	  if (isMantuNeedEmail(body) || isMantuNeedEmail(subject)) return true;
223	  return /\b(job description|jd attached|new (role|position|need|vacancy|opening)|hiring request|backfill|open position)\b/i.test(subject);
224	}
