226	/** Structured parser for the Mantu/Amaris "need is now ACTIVE" recruitment email. */
227	export function parseMantuNeed(text: string): ParsedIntake {
228	  const field = (label: string): string =>
229	    text.match(new RegExp(`^\\s*${label}\\s*:\\s*(.+)$`, "im"))?.[1]?.trim() ?? "";
230	
231	  const title =
232	    text.match(/this need is now active\s*:?\s*(.+)/i)?.[1]?.trim() ||
233	    field("Subject") ||
234	    field("Need") ||
235	    "Consulting Need";
236	
237	  const manager = field("Manager");
238	  const recruiter = field("Recruiter");
239	  const client = field("Client");
240	  const priority = field("Priority");
241	  const locationRaw = field("Location");
242	  const startRaw = field("Start date");
243	  const typeRaw = field("Type") || "Consulting";
244	
245	  const emailMatch = text.match(/[A-Za-z0-9._+-]{1,128}@[A-Za-z0-9-]{1,128}\.[A-Za-z0-9.-]{1,64}/);
246	  const senderName = manager || recruiter || "Hiring Manager";
247	  const senderEmail =
248	    emailMatch?.[0] ??
249	    `${slugify(senderName).replace(/-/g, ".")}@${slugify(client) || "client"}.example`;
250	
251	  // Priority / importance → urgency
252	  let urgency: Urgency = "Standard";
253	  if (/critical/i.test(priority) || /\b1\b/.test(priority) || /high importance|importance:\s*high/i.test(text))
254	    urgency = "Critical";
255	  else if (/urgent/i.test(priority) || /\b2\b/.test(priority)) urgency = "Urgent";
256	
257	  const intent: IntakeIntent = urgency === "Critical" ? "Urgent Hire" : "New Role";
258	
259	  // Skills — the explicit "Skills:" line is authoritative; augment from bullets.
260	  const skillsLine = field("Skills");
261	  const lineSkills = skillsLine
262	    ? skillsLine.split(/[,;]/).map((s) => s.trim()).filter(Boolean)
263	    : [];
264	  const dictSkills = SKILL_DICTIONARY.filter((s) =>
265	    new RegExp(`(^|[^a-z])${escapeRegExp(s)}([^a-z]|$)`, "i").test(text),
266	  );
267	  const requiredSkills = Array.from(new Set([...lineSkills, ...dictSkills])).slice(0, 8);
268	
269	  const minYears = text.match(/minimum[\s]{0,6}(\d{1,2})[\s+]{0,6}years/i)?.[1];
270	  const minYearsExperience = minYears ? parseInt(minYears, 10) : null;
271	
272	  const niceToHaveSkills: string[] = [];
273	  if (/offshore/i.test(text)) niceToHaveSkills.push("Offshore experience");
274	
275	  // Location → region + timezone (best-effort)
276	  const loc = titleCase(locationRaw || "");
277	  const tz = /montreal|toronto|new york|boston/i.test(locationRaw)
278	    ? "EST"
279	    : /london|uk/i.test(locationRaw)
280	      ? "GMT"
281	      : /paris|france|montreal/i.test(locationRaw)
282	        ? "CET"
283	        : "EST";
284	  const regions = loc ? [loc] : ["Global"];
285	
286	  // Start date m/d/yyyy → ISO. Null when the need email doesn't state one —
287	  // createCampaign applies its own default rather than baking a guess in here.
288	  const d = startRaw ? new Date(startRaw) : null;
289	  const targetStartDate: string | null = d && !isNaN(d.getTime()) ? d.toISOString() : null;
290	
291	  const industryExperience = /financial markets|bonds|trading|finance|murex|pricing/i.test(text)
292	    ? ["Fintech"]
293	    : [];
294	
295	  const validationWarnings: ValidationWarning[] = [];
296	  if (!skillsLine && requiredSkills.length < 3)
297	    validationWarnings.push({ field: "requiredSkills", severity: "critical", message: "No explicit skills line and few skills detected." });
298	  validationWarnings.push({ field: "salary", severity: "warning", message: "No salary/rate in the need email. Confirm the band." });
299	  if (!locationRaw)
300	    validationWarnings.push({ field: "location", severity: "warning", message: "No location specified." });
301	
302	  const jobAnalysis: JobAnalysis = {
303	    title,
304	    department: typeRaw || "Consulting",
305	    seniority: minYearsExperience && minYearsExperience >= 8 ? "Staff" : "Senior",
306	    employmentType: /consulting|contract|contractor|freelance/i.test(typeRaw) ? "Contract" : "Full-time",
307	    locationType: /remote/i.test(text) ? "Remote" : /hybrid/i.test(text) ? "Hybrid" : "On-site",
308	    regions,
309	    timezone: tz,
310	    salaryMin: null,
311	    salaryMax: null,
312	    currency: /montreal|toronto|canada/i.test(locationRaw) ? "CAD" : "USD",
313	    equity: /equity|options|esop/i.test(text),
314	    requiredSkills: requiredSkills.length ? requiredSkills : ["Murex", "Finance", "Pricing"],
315	    niceToHaveSkills,
316	    minYearsExperience,
317	    maxYearsExperience: minYearsExperience ? minYearsExperience + 5 : null,
318	    education: "No formal requirement",
319	    industryExperience,
320	    companyStageTarget: ["Enterprise", "Public"],
321	    teamSize: field("Nb people") ? `${field("Nb people")} role(s)` : "Client-embedded",
322	    reportingTo: manager || "Engagement Manager",
323	    urgency,
324	    language: detectLanguage(text),
325	    expectedStartDate: targetStartDate,
326	    validationWarnings,
327	  };
328	
329	  const hasCritical = validationWarnings.some((w) => w.severity === "critical");
330	  return {
331	    sender: { name: senderName, email: senderEmail },
332	    intent,
333	    urgency,
334	    jobAnalysis,
335	    validationWarnings,
336	    clarificationDraft: hasCritical ? buildClarificationEmail(senderName, jobAnalysis, validationWarnings) : null,
337	    confidence: {
338	      title: 0.95,
339	      salary: 0.3,
340	      skills: skillsLine ? 0.95 : 0.7,
341	      location: locationRaw ? 0.92 : 0.5,
342	      seniority: 0.8,
343	    },
344	  };
345	}
