 32	  let token = "";
 33	  if (supabaseEnabled) {
 34	    const supabase = await getServerSupabase();
 35	    if (!supabase) return NextResponse.json({ ok: false, error: "No Supabase client." }, { status: 500 });
 36	    const {
 37	      data: { user },
 38	    } = await supabase.auth.getUser();
 39	    if (!user) return NextResponse.json({ ok: false, error: "Not authenticated." }, { status: 401 });
 40	    const { data: role } = await supabase.rpc("current_profile_role");
 41	    if (!can(role as Role, "manage_tools")) {
 42	      return NextResponse.json({ ok: false, error: "Insufficient permissions." }, { status: 403 });
 43	    }
 44	  } else if (demoLoginEnabled) {
 45	    // Public demo (no Supabase): require the signed admin/admin session cookie so
 46	    // this route isn't reachable anonymously (mirrors the hermes/chat cost gate).
 47	    if (!demoAuthConfigured() || !verifyDemoToken(req.cookies.get(DEMO_COOKIE_NAME)?.value)) {
 48	      return NextResponse.json({ ok: false, error: "Sign in to use this tool." }, { status: 401 });
 49	    }
 50	  }
 51	
 52	  const validated = await validateBody(req, McpTestSchema, { maxBytes: 5_000 });
 53	  if (!validated.ok) return validated.response;
 54	  const { url, apiKeyId } = validated.data;
