 11	export interface RemoteLoad {
 12	  workspaceId: string;
 13	  state: HermesState | null;
 14	  /** Signed-in profile authority. Shared workspace JSON is never authoritative. */
 15	  role: Role;
 16	  /** The row's `updated_at` when loaded — the optimistic-concurrency token. */
 17	  updatedAt: string | null;
 18	}
 19	
 20	export interface SaveResult {
 21	  ok: boolean;
 22	  /** True when the write was rejected because a teammate saved since we loaded. */
 23	  conflict?: boolean;
 24	  /** The new `updated_at` after a successful save (becomes the next token). */
 25	  updatedAt?: string;
 26	  /** On a conflict, the latest shared state to reload. */
 27	  latest?: RemoteLoad;
 28	}
