 30	export interface CurrentUser {
 31	  id: string;
 32	  email: string;
 33	  name: string;
 34	  role: Role;
 35	}
 36	
 37	/** Resolve the signed-in user (browser). Returns null in demo mode / signed out. */
 38	export async function getCurrentUser(): Promise<CurrentUser | null> {
 39	  const supabase = getBrowserSupabase();
 40	  if (!supabase) return null;
 41	  const { data } = await supabase.auth.getUser();
 42	  const u = data.user;
 43	  if (!u) return null;
 44	  const name =
 45	    (u.user_metadata?.full_name as string) ||
 46	    (u.user_metadata?.name as string) ||
 47	    (u.email ? u.email.split("@")[0] : "Operator");
 48	  const { data: role } = await supabase.rpc("current_profile_role");
 49	  return { id: u.id, email: u.email ?? "", name, role: profileRole(role) };
 50	}
