 52	/**
 53	 * Load this user's shared workspace state. `ensure_workspace` (a SECURITY DEFINER
 54	 * function in the migration) finds-or-creates the org workspace by email domain
 55	 * and the caller's profile, returning the workspace id. Returns null only when
 56	 * signed out; otherwise returns the workspace id, its persisted state (or null if
 57	 * the workspace has never been seeded), and the row's `updated_at` token.
 58	 */
 59	export async function loadRemoteState(): Promise<RemoteLoad | null> {
 60	  const supabase = getBrowserSupabase();
 61	  if (!supabase) return null;
 62	  const { data: userData } = await supabase.auth.getUser();
 63	  if (!userData.user) return null;
 64	
 65	  try {
 66	    const { data: workspaceId, error: rpcError } = await supabase.rpc("ensure_workspace");
 67	    if (rpcError || !workspaceId) {
 68	      console.warn("ensure_workspace failed; running in-memory only:", rpcError?.message);
 69	      return { workspaceId: "", state: null, updatedAt: null, role: "viewer" };
 70	    }
 71	    const { data: resolvedRole, error: roleError } = await supabase.rpc("current_profile_role");
 72	    if (roleError) {
 73	      console.warn("current_profile_role failed; using read-only authority:", roleError.message);
 74	    }
 75	    const role = roleError ? "viewer" : profileRole(resolvedRole);
 76	    const { data: row, error: rowError } = await supabase
 77	      .from("workspace_state")
 78	      .select("state, updated_at")
 79	      .eq("workspace_id", workspaceId)
 80	      .maybeSingle();
 81	    if (rowError) {
 82	      // A FAILED read must not masquerade as an EMPTY workspace: the hydrate
 83	      // path seeds-and-saves when it sees `state: null` with a workspaceId,
 84	      // which would overwrite the whole shared blob during a transient backend
 85	      // blip. Run in-memory only (no workspaceId → nothing ever persists).
 86	      console.warn("workspace_state load failed; running in-memory only:", rowError.message);
 87	      return { workspaceId: "", state: null, updatedAt: null, role };
 88	    }
 89	    return {
 90	      workspaceId: workspaceId as string,
 91	      state: (row?.state as HermesState) ?? null,
 92	      updatedAt: (row?.updated_at as string) ?? null,
 93	      role,
 94	    };
 95	  } catch (err) {
 96	    console.warn("loadRemoteState error:", err);
 97	    return { workspaceId: "", state: null, updatedAt: null, role: "viewer" };
 98	  }
 99	}
100	
101	/**
102	 * Persist the full workspace state document with OPTIMISTIC CONCURRENCY.
103	 *
104	 * `expectedUpdatedAt` is the `updated_at` the caller last loaded. The write only
105	 * lands if the row STILL has that timestamp — so if a teammate saved in the
106	 * meantime, the conditional update matches zero rows and we report a conflict
107	 * (with the latest state) instead of silently clobbering their change. The shared
108	 * workspace is one JSONB document, so last-write-wins would otherwise lose a whole
109	 * concurrent edit with no warning to anyone.
110	 *
111	 * When `expectedUpdatedAt` is null (first save, the row does not exist yet) we
112	 * upsert to create it.
113	 */
114	export async function saveRemoteState(
115	  workspaceId: string,
116	  state: HermesState,
117	  expectedUpdatedAt: string | null,
118	): Promise<SaveResult> {
119	  const supabase = getBrowserSupabase();
120	  if (!supabase || !workspaceId) return { ok: false };
121	  const sharedState = stripSharedRole(state);
122	  try {
123	    if (expectedUpdatedAt === null) {
124	      // No known prior version — create (or adopt) the row. `updated_at` is owned by
125	      // the DB (column default on insert, the touch_updated_at trigger on update),
126	      // so we read it back as the authoritative concurrency token rather than
127	      // trusting a client clock the trigger would overwrite anyway.
128	      const { data, error } = await supabase
129	        .from("workspace_state")
130	        .upsert({ workspace_id: workspaceId, state: sharedState }, { onConflict: "workspace_id" })
131	        .select("updated_at")
132	        .maybeSingle();
133	      if (error) {
134	        console.warn("saveRemoteState (insert) failed:", error.message);
135	        return { ok: false };
136	      }
137	      return { ok: true, updatedAt: (data?.updated_at as string) ?? undefined };
138	    }
139	
140	    // Conditional update — only overwrite the exact version we loaded. The
141	    // touch_updated_at trigger assigns the new updated_at; we read it back as the
142	    // authoritative next token (never via a JS Date, which would drop microseconds).
143	    const { data, error } = await supabase
144	      .from("workspace_state")
145	      .update({ state: sharedState })
146	      .eq("workspace_id", workspaceId)
147	      .eq("updated_at", expectedUpdatedAt)
148	      .select("updated_at")
149	      .maybeSingle();
150	    if (error) {
151	      console.warn("saveRemoteState (update) failed:", error.message);
152	      return { ok: false };
153	    }
154	    if (!data) {
155	      // Zero rows matched → a teammate wrote since we loaded. Return the latest
156	      // state so the caller can reload instead of clobbering it.
157	      const { data: latestRow } = await supabase
158	        .from("workspace_state")
159	        .select("state, updated_at")
160	        .eq("workspace_id", workspaceId)
161	        .maybeSingle();
162	      return {
163	        ok: false,
164	        conflict: true,
165	        latest: {
166	          workspaceId,
167	          state: (latestRow?.state as HermesState) ?? null,
168	          updatedAt: (latestRow?.updated_at as string) ?? null,
169	          role: "viewer",
170	        },
171	      };
172	    }
173	    return { ok: true, updatedAt: data.updated_at as string };
174	  } catch (err) {
175	    console.warn("saveRemoteState error:", err);
176	    return { ok: false };
177	  }
178	}
