 36	export async function GET(req: NextRequest) {
 37	  const url = req.nextUrl;
 38	  const mode = url.searchParams.get("hub.mode");
 39	  const token = url.searchParams.get("hub.verify_token");
 40	  const challenge = url.searchParams.get("hub.challenge") ?? "";
 41	  if (mode === "subscribe" && VERIFY_TOKEN() && token === VERIFY_TOKEN()) {
 42	    return new NextResponse(challenge, { status: 200 });
 43	  }
 44	  return NextResponse.json({ ok: false }, { status: 403 });
 45	}
