 47	export async function POST(req: NextRequest) {
 48	  const rawBody = await req.text();
 49	  const signature = req.headers.get("x-hub-signature-256");
 50	  if (!verifyMetaSignature(rawBody, signature, APP_SECRET())) {
 51	    return NextResponse.json({ ok: false, reason: "Bad signature." }, { status: 401 });
 52	  }
 53	
 54	  const supabase = getServiceSupabase();
 55	  if (!supabase) {
 56	    safeLog("whatsapp webhook: not configured", { hasSupabase: false });
 57	    return NextResponse.json({ ok: false, reason: "Service client unavailable." }, { status: 503 });
 58	  }
 59	
 60	  let payload: unknown;
 61	  try {
 62	    payload = JSON.parse(rawBody);
 63	  } catch {
 64	    return NextResponse.json({ ok: true }); // not JSON we understand; ack
 65	  }
