 67	  // Delivery/read receipts are signed provider facts, never candidate replies.
 68	  // Resolve the sender without requiring it to remain active so an event already
 69	  // in flight can still reconcile after an operator pauses the sender. A known
 70	  // sender's failed persistence is retryable: acknowledging it would silently
 71	  // lose a durable delivery fact.
 72	  let retryableReceiptFailure = false;
 73	  for (const receipt of parseWhatsAppDeliveryStatuses(payload)) {
 74	    try {
 75	      if (receipt.occurredAt > Date.now() + 5 * 60 * 1_000) {
 76	        safeLog("whatsapp delivery receipt ignored: future timestamp", { status: receipt.status });
 77	        continue;
 78	      }
 79	      const { data: sender, error: senderErr } = await supabase
 80	        .from("whatsapp_senders")
 81	        .select("id, workspace_id")
 82	        .eq("meta_phone_number_id", receipt.senderPhoneNumberId)
 83	        .maybeSingle();
 84	      if (senderErr) {
 85	        retryableReceiptFailure = true;
 86	        safeLog("whatsapp delivery sender lookup error", { message: senderErr.message });
 87	        continue;
 88	      }
 89	      if (!sender) {
 90	        continue;
 91	      }
 92	      const { data: event, error: eventErr } = await supabase.rpc("record_whatsapp_delivery_event", {
 93	        p_workspace_id: sender.workspace_id,
 94	        p_sender_id: sender.id,
 95	        p_provider_message_id: receipt.providerMessageId,
 96	        p_event_status: receipt.status,
 97	        p_provider_occurred_at: new Date(receipt.occurredAt).toISOString(),
 98	        p_provider_error_code: receipt.providerErrorCode ?? null,
 99	      });
100	      const receiptDecision = decideWhatsAppReceiptAcknowledgement({
101	        senderKnown: true,
102	        rpcResult: eventErr
103	          ? null
104	          : (event as { recorded?: boolean; retryable?: boolean; reason?: string } | null),
105	      });
106	      if (!receiptDecision.acknowledge) {
107	        retryableReceiptFailure = true;
108	        safeLog("whatsapp delivery receipt reconciliation error", { message: eventErr?.message ?? receiptDecision.reason });
109	      }
110	    } catch (err) {
111	      retryableReceiptFailure = true;
112	      safeLog("whatsapp delivery receipt processing error", {
113	        message: err instanceof Error ? err.message : "unknown",
114	      });
115	    }
116	  }
117	
118	  // The inbound row is committed before any model call. The lease-backed
119	  // processor makes a Meta redelivery, a webhook restart, and cron recovery
120	  // converge on that stored row rather than losing it after a mid-pipeline
121	  // error or composing two candidate replies.
122	  let retryableInboundFailure = false;
123	  for (const msg of parseWhatsAppWebhook(payload)) {
124	    try {
125	      // Resolve a tenant from Meta's signed phone-number ID. An environment
126	      // workspace fallback would let a valid event cross tenant boundaries.
127	      const { data: sender, error: senderErr } = await supabase
128	        .from("whatsapp_senders")
129	        .select("id, workspace_id, status")
130	        .eq("meta_phone_number_id", msg.senderPhoneNumberId)
130	        .eq("meta_phone_number_id", msg.senderPhoneNumberId)
131	        .maybeSingle();
132	      if (senderErr) {
133	        retryableInboundFailure = true;
134	        safeLog("whatsapp sender lookup error", { message: senderErr.message });
135	        continue;
136	      }
137	      if (!sender) {
138	        continue;
139	      }
140	      const inboundDisposition = decideWhatsAppInboundDisposition({
141	        senderStatus: sender.status,
142	        isOptOut: isWhatsAppOptOut(msg.text),
143	      });
144	      const workspaceId = sender.workspace_id;
145	      const recipientE164 = normalizeWhatsAppAddress(msg.from);
146	      if (!recipientE164) {
147	        safeLog("whatsapp inbound: invalid sender address", { providerId: msg.providerId });
148	        continue;
149	      }
150	      const localNow = Date.now();
151	      const receivedAt = Number.isFinite(msg.timestamp) && msg.timestamp > 0 && msg.timestamp <= localNow + 5 * 60 * 1_000
152	        ? new Date(msg.timestamp).toISOString()
153	        : new Date(localNow).toISOString();
154	
155	      // 1. Store inbound, idempotent on Meta's message id.
156	      const { data: inserted, error: insErr } = await supabase
157	        .from("messages_inbound")
158	        .insert({
159	          workspace_id: workspaceId,
160	          channel: "WhatsApp",
161	          from_address: recipientE164,
162	          body: msg.text,
163	          provider_id: msg.providerId,
164	          received_at: receivedAt,
165	          whatsapp_sender_id: sender.id,
166	          processed: inboundDisposition.initiallyProcessed,
167	        })
168	        .select("id")
169	        .maybeSingle();
170	      let inboundId = inserted?.id;
171	      let existingInboundProcessed = inboundDisposition.initiallyProcessed;
172	      if (insErr?.code === "23505") {
173	        // A prior delivery may have stored the row before the process failed.
174	        // Reclaim it through the same lease instead of treating a duplicate as
175	        // proof that it was successfully processed.
176	        const { data: existing, error: existingErr } = await supabase
177	          .from("messages_inbound")
178	          .select("id, processed")
179	          .eq("workspace_id", workspaceId)
180	          .eq("channel", "WhatsApp")
181	          .eq("provider_id", msg.providerId)
182	          .maybeSingle();
183	        if (existingErr || !existing) {
184	          retryableInboundFailure = true;
185	          safeLog("whatsapp inbound duplicate lookup error", { message: existingErr?.message ?? "not found" });
186	          continue;
187	        }
188	        inboundId = existing.id;
189	        existingInboundProcessed = existing.processed === true;
190	      } else if (insErr) {
191	        retryableInboundFailure = true;
192	        safeLog("whatsapp inbound insert error", { message: insErr.message });
193	        continue;
194	      }
195	      if (!inboundId) {
196	        retryableInboundFailure = true;
197	        safeLog("whatsapp inbound persistence returned no id", { providerId: msg.providerId });
198	        continue;
199	      }
200	
201	      if (!inboundDisposition.process) {
202	        // If an inactive-sender event is a redelivery of a row created before
203	        // the pause, record the current non-dispatch decision too. Recovery
204	        // only selects unfinished rows, so reactivation cannot draft this text.
205	        if (!existingInboundProcessed) {
206	          const { error: blockErr } = await supabase
207	            .from("messages_inbound")
208	            .update({ processed: true })
209	            .eq("id", inboundId)
210	            .eq("workspace_id", workspaceId)
211	            .eq("processed", false);
212	          if (blockErr) {
213	            retryableInboundFailure = true;
214	            safeLog("whatsapp inactive inbound disposition update error", { message: blockErr.message });
215	          }
216	        }
217	        continue;
218	      }
219	
220	      const result = await processStoredWhatsAppInbound(supabase, { inboundId, senderId: sender.id });
221	      if (result.outcome === "retry") {
222	        retryableInboundFailure = true;
223	        safeLog("whatsapp inbound processing deferred", { reason: result.reason });
224	      }
225	    } catch (err) {
226	      retryableInboundFailure = true;
227	      safeLog("whatsapp webhook processing error", {
228	        message: err instanceof Error ? err.message : "unknown",
229	      });
230	    }
231	  }
232	
233	  try {
234	    const recovery = await recoverPendingWhatsAppInbound(supabase, 5);
235	    if (recovery.retryable > 0) retryableInboundFailure = true;
236	  } catch (err) {
237	    retryableInboundFailure = true;
238	    safeLog("whatsapp inbound recovery error", { message: err instanceof Error ? err.message : "unknown" });
239	  }
240	
241	  // Opportunistic drain: Meta calls this webhook for every delivery/read
242	  // receipt too, so due queued messages go out with near-human latency even
243	  // though Vercel Hobby only allows a daily cron (the /api/cron backstop).
244	  try {
245	    await dispatchDue(supabase, 5);
246	  } catch (err) {
247	    safeLog("whatsapp webhook: drain error", { message: err instanceof Error ? err.message : "unknown" });
248	  }
249	
250	  if (retryableReceiptFailure || retryableInboundFailure) {
251	    return NextResponse.json(
252	      { ok: false, reason: "Retryable WhatsApp persistence failure." },
253	      { status: 503 },
254	    );
255	  }
256	  return NextResponse.json({ ok: true });
257	}

