  5	import { NextResponse, type NextRequest } from "next/server";
  6	import { getServerSupabase, getServiceSupabase } from "@/lib/supabase/server";
  7	import { supabaseEnabled } from "@/lib/supabase/config";
  8	import { can } from "@/lib/rbac";
  9	import type { EmailConnection, Role } from "@/lib/types";
