 11	import { getAccessTokenForReading } from "@/lib/email-oauth";
 12	import { encryptSecret, decryptSecret, encryptionRequiredButMissing } from "@/lib/crypto-secrets";
 13	import {
 14	  listInboundGmail,
 15	  getGmailMessage,
 16	  listInboundGraph,
 17	  getGraphMessage,
 18	  type InboundMessage,
 19	} from "@/lib/email-sync";
 20	import { PUBLIC_DEMO_DRY_RUN_DETAIL, publicDemoSideEffectsDisabled } from "@/lib/server/demo-side-effects";
 21	
 22	/** Maximum messages returned across ALL connections in a single sync. */
 23	const TOTAL_MESSAGE_CAP = 50;
 24	
 25	/** Maximum body characters stored per message (avoids huge JSON payloads). */
 26	const BODY_TRUNCATE = 8_000;
 27	
 28	/** Maximum email connections processed per sync (prevents timeout on large workspaces). */
 29	const MAX_CONNECTIONS = 10;
 30	
 31	/** Soft wall-clock deadline per sync request (ms). Remaining connections defer to next run. */
 32	const SYNC_DEADLINE_MS = 45_000;
 33	
 34	export async function POST(req: NextRequest) {
 35	  // ── 1. Auth ────────────────────────────────────────────────────────────────
 36	  // Supabase is required — no demo bypass for a route that touches live mailboxes.
 37	  if (!supabaseEnabled) {
 38	    return NextResponse.json(
 39	      { ok: false, error: "Authentication backend not configured." },
 40	      { status: 503 },
 41	    );
 42	  }
 43	
 44	  const supabase = await getServerSupabase();
 45	  if (!supabase) {
 46	    return NextResponse.json(
 47	      { ok: false, error: "No Supabase client." },
 48	      { status: 500 },
 49	    );
 50	  }
 51	
 52	  const {
 53	    data: { user },
 54	  } = await supabase.auth.getUser();
 55	  if (!user) {
 56	    return NextResponse.json({ ok: false, error: "Not authenticated." }, { status: 401 });
 57	  }
 58	  const userId = user.id;
 59	
 60	  // ── 2. Role check ──────────────────────────────────────────────────────────
 61	  const { data: role } = await supabase.rpc("current_profile_role");
 62	  if (!can(role as Role, "source")) {
 63	    return NextResponse.json(
 64	      { ok: false, error: "Insufficient permissions." },
 65	      { status: 403 },
 66	    );
 67	  }
 68	
 69	  // ── 3. Rate limit ──────────────────────────────────────────────────────────
 70	  // Sync is expensive (multiple upstream GETs per connection). 10/min per caller.
 71	  const rl = checkRateLimit(
 72	    rateLimitKey(req, "email-sync", userId),
 73	    { windowMs: 60_000, max: 10 },
 74	  );
 75	  if (!rl.ok) return tooManyRequests(rl.retryAfterSec);
 76	
 77	  // ── 4. Resolve workspace ───────────────────────────────────────────────────
 78	  const { data: wid } = await supabase.rpc("current_workspace_id");
 79	  if (!wid) {
 80	    return NextResponse.json(
 81	      { ok: false, error: "Workspace not found." },
 82	      { status: 400 },
 83	    );
 84	  }
 85	
 86	  if (publicDemoSideEffectsDisabled()) {
 87	    return NextResponse.json({ ok: true, status: "dry-run", messages: [], errors: [], detail: PUBLIC_DEMO_DRY_RUN_DETAIL });
 88	  }
 89	
 90	  // ── 5. Load email connections (service-role — bypasses RLS for secrets) ────
 91	  const svc = getServiceSupabase();
 92	  if (!svc) {
 93	    return NextResponse.json(
 94	      { ok: false, error: "Service client unavailable." },
 95	      { status: 500 },
 96	    );
 97	  }
 98	
 99	  const { data: rows, error: connErr } = await svc
100	    .from("email_connections")
101	    .select("id, workspace_id, seat_id, provider, account_email, access_token, refresh_token, expires_at, scope")
102	    .eq("workspace_id", wid);
103	
104	  if (connErr) {
105	    console.error("[email-sync] email_connections query error", { code: connErr.code });
106	    return NextResponse.json(
107	      { ok: false, error: "Failed to load email connections." },
108	      { status: 500 },
109	    );
110	  }
111	
112	  const connections = rows ?? [];
113	  const messages: (InboundMessage & { seatId: string })[] = [];
114	  const errors: string[] = [];
115	  let totalCollected = 0;
116	  let connectionsProcessed = 0;
117	  const deadline = Date.now() + SYNC_DEADLINE_MS;
118	
119	  // ── 6. Sync each connection ────────────────────────────────────────────────
120	  for (const row of connections) {
121	    if (totalCollected >= TOTAL_MESSAGE_CAP) break;
122	    if (connectionsProcessed >= MAX_CONNECTIONS) {
123	      errors.push("Connection cap reached; remaining mailboxes will sync next run.");
124	      break;
125	    }
126	    if (Date.now() > deadline) {
127	      errors.push("Sync deadline reached; remaining mailboxes will sync next run.");
128	      break;
129	    }
130	    connectionsProcessed++;
131	
132	    // Tokens are encrypted at rest; decrypt for use. Keep the decrypted original to
133	    // detect a refresh below.
134	    const origAccessToken = decryptSecret(row.access_token);
135	    const conn: EmailConnection = {
136	      id: row.id,
137	      seatId: row.seat_id,
138	      provider: row.provider,
139	      accountEmail: row.account_email,
140	      accessToken: origAccessToken,
141	      refreshToken: row.refresh_token ? decryptSecret(row.refresh_token) : row.refresh_token,
142	      expiresAt: row.expires_at,
143	      scope: row.scope ?? "",
144	      connectedAt: "",
145	      updatedAt: "",
146	    };
147	
148	    // Get (and possibly refresh) the access token — never log it.
149	    const token = await getAccessTokenForReading(conn);
150	    if (!token) {
151	      errors.push(`No token for connection ${row.id} (${row.provider})`);
152	      continue;
153	    }
154	
155	    // Persist a refreshed token if it changed. Fail closed: never write a refreshed
156	    // token in cleartext when production requires encryption at rest but no key is
157	    // configured — skip the persist (this sync still completes with the in-memory
158	    // token) rather than silently degrade the stored credential to plaintext.
159	    if (
160	      token !== origAccessToken ||
161	      conn.expiresAt !== row.expires_at
162	    ) {
163	      if (encryptionRequiredButMissing()) {
164	        errors.push(`Refreshed token for ${row.id} not persisted (server encryption key not configured).`);
165	      } else {
166	        await svc
167	          .from("email_connections")
168	          .update({
169	            access_token: encryptSecret(conn.accessToken),
170	            expires_at: conn.expiresAt,
171	            updated_at: new Date().toISOString(),
172	          })
173	          .eq("id", conn.id);
174	      }
175	    }
176	
177	    const remaining = TOTAL_MESSAGE_CAP - totalCollected;
178	
179	    if (row.provider === "Gmail API") {
180	      let stubs: { id: string; threadId: string }[] = [];
181	      try {
182	        stubs = await listInboundGmail(token, Math.min(remaining, 25));
183	      } catch (err) {
184	        const msg = err instanceof Error ? err.message : "Gmail list failed";
185	        errors.push(`Gmail list (${row.id}): ${msg}`);
186	        continue;
187	      }
188	
189	      for (const stub of stubs) {
190	        if (totalCollected >= TOTAL_MESSAGE_CAP) break;
191	        try {
192	          const msg = await getGmailMessage(token, stub.id);
193	          if (msg) {
194	            const gmailBody = msg.body.length > BODY_TRUNCATE
195	              ? msg.body.slice(0, BODY_TRUNCATE) + "\n\n[… message truncated at 8000 characters; full message is in the mailbox]"
196	              : msg.body;
197	            messages.push({
198	              ...msg,
199	              body: gmailBody,
200	              seatId: conn.seatId,
201	            });
202	            totalCollected++;
203	          }
204	        } catch (err) {
205	          const detail = err instanceof Error ? err.message : "unknown";
206	          errors.push(`Gmail message ${stub.id}: ${detail}`);
207	        }
208	      }
209	    } else if (row.provider === "Microsoft Graph") {
210	      let stubs: { id: string; conversationId: string }[] = [];
211	      try {
212	        stubs = await listInboundGraph(token, Math.min(remaining, 25));
213	      } catch (err) {
214	        const msg = err instanceof Error ? err.message : "Graph list failed";
215	        errors.push(`Graph list (${row.id}): ${msg}`);
216	        continue;
217	      }
218	
219	      for (const stub of stubs) {
220	        if (totalCollected >= TOTAL_MESSAGE_CAP) break;
221	        try {
222	          const msg = await getGraphMessage(token, stub.id);
223	          if (msg) {
224	            const graphBody = msg.body.length > BODY_TRUNCATE
225	              ? msg.body.slice(0, BODY_TRUNCATE) + "\n\n[… message truncated at 8000 characters; full message is in the mailbox]"
226	              : msg.body;
227	            messages.push({
228	              ...msg,
229	              body: graphBody,
230	              seatId: conn.seatId,
231	            });
232	            totalCollected++;
233	          }
234	        } catch (err) {
235	          const detail = err instanceof Error ? err.message : "unknown";
236	          errors.push(`Graph message ${stub.id}: ${detail}`);
237	        }
238	      }
239	    } else {
240	      errors.push(`Unknown provider for connection ${row.id}: ${row.provider}`);
241	    }
242	  }
243	
244	  // Log counts only — no token, no message bodies.
245	  console.log("[email-sync] sync complete", {
246	    connections: connections.length,
247	    messages: messages.length,
248	    errors: errors.length,
249	  });
