 24	/** Stamp `at`, push onto the bounded ring buffer, and notify every subscriber.
 25	 *  Never throws — a subscriber error is caught and swallowed so it can never
 26	 *  break the store action that emitted the event. */
 27	export function emit(e: Omit<AgentEvent, "at"> & { at?: number }): void {
 28	  const event: AgentEvent = { ...e, at: e.at ?? Date.now() };
 29	  buffer.push(event);
 30	  if (buffer.length > CAPACITY) buffer.shift();
 31	  subscribers.forEach((fn) => {
 32	    try {
 33	      fn(event);
 34	    } catch {
 35	      /* a misbehaving subscriber must never break the emitting action */
 36	    }
 37	  });
 38	}
