 40	/** Subscribe to future events. Returns an unsubscribe function. */
 41	export function subscribe(fn: (e: AgentEvent) => void): () => void {
 42	  subscribers.add(fn);
 43	  return () => {
 44	    subscribers.delete(fn);
 45	  };
 46	}
