 56	/**
 57	 * Which seat "owns" a candidate for replay purposes — the seat behind the
 58	 * candidate's EARLIEST logged outreach-ledger contact attempt. The ledger
 59	 * (OutreachLedgerEntry.seatId) is the only place a real seat is attributed to
 60	 * a candidate; everything else (OutreachMessage, ClassifiedReply, Booking)
 61	 * carries no seatId. Candidates with no ledger history yet simply have no
 62	 * entry in the returned map (seatId stays undefined for their events).
 63	 */
 64	function buildCandidateSeatMap(ledger: OutreachLedgerEntry[]): Map<string, string> {
 65	  const earliest = new Map<string, { seatId: string; at: number }>();
 66	  for (const entry of ledger) {
 67	    const at = toMs(entry.at, Number.POSITIVE_INFINITY);
 68	    const existing = earliest.get(entry.candidateId);
 69	    if (!existing || at < existing.at) {
 70	      earliest.set(entry.candidateId, { seatId: entry.seatId, at });
 71	    }
 72	  }
 73	  const out = new Map<string, string>();
 74	  for (const [candidateId, v] of earliest) out.set(candidateId, v.seatId);
 75	  return out;
 76	}
