 99	  const candidateById = new Map(state.candidates.map((c) => [c.id, c]));
100	
101	  for (const c of state.candidates) {
102	    const sourcedAt = toMs(c.createdAt, 0);
103	    const seatId = candidateSeat.get(c.id);
104	    events.push({
105	      at: sourcedAt,
106	      kind: "source",
107	      candidateId: c.id,
108	      seatId,
109	      label: `${c.name} sourced from ${c.sourcePlatform}`,
110	    });
111	    events.push({
112	      at: sourcedAt + 1,
113	      kind: "score",
