121	  // set) but with no OutreachMessage on record — covers seed/legacy data that
122	  // predates the outreach array. Skipped whenever a real draft/approve pair
123	  // already exists below, so nothing is double-counted.
124	  const candidatesWithOutreach = new Set(state.outreach.map((m) => m.candidateId));
125	  for (const c of state.candidates) {
126	    if (c.lastContactedAt && !candidatesWithOutreach.has(c.id)) {
127	      events.push({
128	        at: toMs(c.lastContactedAt, toMs(c.createdAt, 0)),
129	        kind: "approve",
130	        candidateId: c.id,
131	        seatId: candidateSeat.get(c.id),
132	        label: `${c.name} contacted`,
133	      });
134	    }
135	  }
136	
137	  for (const m of state.outreach) {
138	    const name = candidateById.get(m.candidateId)?.name ?? m.candidateId;
139	    const seatId = candidateSeat.get(m.candidateId);
140	    const draftAt = toMs(m.createdAt, 0);
141	    events.push({
142	      at: draftAt,
143	      kind: "draft",
144	      candidateId: m.candidateId,
145	      seatId,
146	      label: `${m.channel} draft for ${name}: ${m.subject}`,
147	    });
148	    if (m.status === "Approved" || m.status === "Pending Manual Send" || m.status === "Scheduled") {
149	      const approvedAt = Math.max(toMs(m.sentAt ?? m.scheduledFor, draftAt + 1), draftAt + 1);
150	      events.push({
151	        at: approvedAt,
152	        kind: "approve",
153	        candidateId: m.candidateId,
154	        seatId,
155	        label: m.sentAt
156	          ? `${m.channel} sent to ${name}: ${m.subject}`
157	          : `${m.channel} approved for ${name}: ${m.subject}`,
158	      });
159	    }
160	  }
161	
162	  for (const r of state.replies) {
163	    const name = candidateById.get(r.candidateId)?.name ?? r.candidateId;
164	    events.push({
165	      at: toMs(r.receivedAt, 0),
166	      kind: "reply",
167	      candidateId: r.candidateId,
168	      seatId: candidateSeat.get(r.candidateId),
169	      label: `${r.intent} reply from ${name}`,
170	    });
171	  }
172	
173	  for (const b of state.bookings) {
174	    events.push({
175	      at: toMs(b.createdAt, 0),
176	      kind: "book",
177	      candidateId: b.candidateId,
178	      seatId: candidateSeat.get(b.candidateId),
179	      label: `Interview booked: ${b.candidateName} with ${b.interviewer}`,
180	    });
181	  }
182	
183	  for (const rep of state.reports) {
184	    events.push({
185	      at: toMs(rep.generatedAt, 0),
186	      kind: "report",
187	      label: `Weekly report generated: ${rep.campaignTitle}`,
188	    });
189	  }
190	
191	  // Campaign-wide re-score sweeps (the only "score" Activity the store ever
192	  // logs — see updateCampaign in store.ts) are genuinely new information not
193	  // captured anywhere above, so they're folded in too. Per-candidate outreach/
194	  // reply/booking Activities are deliberately NOT replayed here — they'd just
