212	/** Index of the first event with `at > t` (i.e. count of events with `at <= t`). */
213	function upperBound(events: ReplayEvent[], t: number): number {
214	  let lo = 0;
215	  let hi = events.length;
216	  while (lo < hi) {
217	    const mid = (lo + hi) >>> 1;
218	    if (events[mid].at <= t) lo = mid + 1;
219	    else hi = mid;
220	  }
221	  return lo;
222	}
223	
224	/** Index of the first event with `at >= t`. */
225	function lowerBound(events: ReplayEvent[], t: number): number {
226	  let lo = 0;
227	  let hi = events.length;
228	  while (lo < hi) {
229	    const mid = (lo + hi) >>> 1;
230	    if (events[mid].at < t) lo = mid + 1;
231	    else hi = mid;
232	  }
233	  return lo;
234	}
