 35	const DELIMITER_RE = /^\s*-{3,}\s*$/;
 36	
 37	/** Splits a pasted multi-role brief into per-role blocks on a line containing
 38	 *  only `---` (3+ dashes, optionally padded with whitespace). Pure string
 39	 *  parsing — no network, no parsing library, offline by construction. */
 40	function splitRoleBlocks(raw: string): string[] {
 41	  const lines = raw.split(/\r?\n/);
 42	  const blocks: string[] = [];
 43	  let current: string[] = [];
 44	  for (const line of lines) {
 45	    if (DELIMITER_RE.test(line)) {
 46	      blocks.push(current.join("\n").trim());
 47	      current = [];
 48	    } else {
 49	      current.push(line);
 50	    }
 51	  }
 52	  blocks.push(current.join("\n").trim());
 53	  return blocks.map((b) => b.trim()).filter(Boolean);
 54	}
