 36	-- Persist Meta provider acceptance atomically with the claimed ledger row.
 37	-- If this fails after Meta accepted the request, the row deliberately remains
 38	-- dispatching: a worker must never retry an ambiguous external send.
 39	create or replace function public.record_whatsapp_provider_acceptance(
 40	  p_message_id uuid,
 41	  p_delivery_attempt_id uuid,
 42	  p_provider_message_id text
 43	) returns json
 44	language plpgsql
 45	security definer
 46	set search_path = public
 47	as $$
 48	declare
 49	  outbound public.messages_outbound%rowtype;
 50	begin
 51	  if coalesce(auth.role(), '') <> 'service_role' then
 52	    return json_build_object('allowed', false, 'reason', 'service-only');
 53	  end if;
 54	  if p_provider_message_id is null or length(p_provider_message_id) < 1 or length(p_provider_message_id) > 512 then
 55	    return json_build_object('allowed', false, 'reason', 'invalid-provider-message-id');
 56	  end if;
 57	
 58	  select * into outbound
 59	    from public.messages_outbound
 60	    where id = p_message_id
 61	    for update;
 62	  if not found then return json_build_object('allowed', false, 'reason', 'message-not-found'); end if;
 63	  if outbound.channel <> 'WhatsApp' then return json_build_object('allowed', false, 'reason', 'wrong-channel'); end if;
 64	  if outbound.delivery_attempt_id is distinct from p_delivery_attempt_id then
 65	    return json_build_object('allowed', false, 'reason', 'attempt-mismatch');
 66	  end if;
 67	  if outbound.status = 'sent' and outbound.provider_message_id = p_provider_message_id then
 68	    return json_build_object('allowed', true, 'reason', 'already-recorded');
 69	  end if;
 70	  if outbound.status <> 'dispatching' then return json_build_object('allowed', false, 'reason', 'not-dispatching'); end if;
 71	
 72	  update public.messages_outbound
 73	    set status = 'sent',
 74	        sent_at = now(),
 75	        provider_message_id = p_provider_message_id
 76	    where id = outbound.id;
 77	
 78	  update public.outreach_ledger
 79	    set status = 'sent',
 80	        reason = null
 81	    where workspace_id = outbound.workspace_id
 82	      and outbound_message_id = outbound.id
 83	      and status = 'claimed';
 84	
 85	  return json_build_object('allowed', true, 'reason', 'recorded');
 86	end;
 87	$$;
