 69	function spanDaysFrom(dates: string[]): number {
 70	  const ts = dates.map((d) => new Date(d).getTime()).filter((n) => Number.isFinite(n));
 71	  if (ts.length === 0) return 1;
 72	  const spanMs = Math.max(...ts) - Math.min(...ts);
 73	  return Math.max(1, round(spanMs / 86_400_000, 1));
 74	}
