 71	export function CompliancePosture() {
 72	  const activities = useActivities();
 73	  const candidates = useCandidates();
 74	  const outreach = useOutreach();
 75	  const seats = useSeats();
 76	  const suppression = useSuppression();
 77	
 78	  const now = Date.now();
 79	
 80	  /* ---- PII reveal audit --------------------------------------------------
 81	     recordPiiReveal (store.ts) writes an activity of type "compliance" every
 82	     time a recruiter reveals a candidate's contact details. */
 83	  const piiReveals = React.useMemo(
 84	    () => activities.filter((a) => a.type === "compliance"),
 85	    [activities],
 86	  );
 87	  const lastReveal = React.useMemo(
 88	    () => piiReveals.reduce<string | null>((latest, a) => (!latest || a.createdAt > latest ? a.createdAt : latest), null),
 89	    [piiReveals],
 90	  );
 91	
 92	  /* ---- Suppression adherence ---------------------------------------------
 93	     A "breach" is either (a) a candidate already flagged suppressed/
 94	     do-not-contact who still has an outreach message sitting in a status
 95	     that could reach them, or (b) any candidate whose email — or its
 96	     domain — matches an active Fleet suppression entry while a message to
 97	     them is still pending/queued. (b) is what actually catches entries
 98	     added straight to the Fleet suppression list (e.g. an excluded
 99	     competitor domain) that never touched the candidate's complianceFlags. */
100	  const activeSuppression = React.useMemo(
101	    () => suppression.filter((s) => !s.expiresAt || new Date(s.expiresAt).getTime() > now),
102	    [suppression, now],
103	  );
104	  const flaggedCandidates = React.useMemo(
105	    () => candidates.filter((c) => c.complianceFlags.suppressed || c.complianceFlags.doNotContact),
106	    [candidates],
107	  );
108	  const suppressionBreaches = React.useMemo(() => {
109	    const flaggedBreaches = flaggedCandidates.filter((c) =>
110	      outreach.some((m) => m.candidateId === c.id && PENDING_SEND_STATUSES.has(m.status)),
111	    );
112	    const candidateById = new Map(candidates.map((c) => [c.id, c] as const));
113	    const listBreaches: Candidate[] = [];
114	    for (const m of outreach) {
115	      if (!PENDING_SEND_STATUSES.has(m.status)) continue;
116	      const candidate = candidateById.get(m.candidateId);
117	      if (!candidate) continue;
118	      const email = candidate.email.toLowerCase();
119	      const domain = email.split("@")[1] ?? "";
120	      const matchesSuppression = activeSuppression.some(
121	        (s) =>
122	          (s.type === "email" && s.value.toLowerCase() === email) ||
123	          (s.type === "domain" && domain !== "" && s.value.toLowerCase() === domain),
124	      );
125	      if (matchesSuppression) listBreaches.push(candidate);
126	    }
127	    const byId = new Map<string, Candidate>();
128	    for (const c of [...flaggedBreaches, ...listBreaches]) byId.set(c.id, c);
129	    return Array.from(byId.values());
130	  }, [flaggedCandidates, outreach, candidates, activeSuppression]);
131	
132	  /* ---- Rate-limit adherence ----------------------------------------------
133	     Each seat enforces its own dailyLimit; this reads the live counters. */
134	  const seatsOverCap = React.useMemo(() => seats.filter((s) => s.sentToday > s.dailyLimit), [seats]);
135	  const seatsWithinCap = seats.length - seatsOverCap.length;
136	
137	  /* ---- GDPR / data-rights honoring ---------------------------------------- */
138	  const gdprExports = React.useMemo(() => candidates.filter((c) => c.complianceFlags.gdprExportRequested).length, [candidates]);
139	  const anonymized = React.useMemo(() => candidates.filter((c) => c.complianceFlags.anonymized).length, [candidates]);
140	  const doNotContact = React.useMemo(() => candidates.filter((c) => c.complianceFlags.doNotContact).length, [candidates]);
141	
142	  return (
143	    <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-4">
144	      <Tile
145	        icon={<ShieldCheck className="h-5 w-5" aria-hidden />}
146	        tone={piiReveals.length > 0 ? "success" : "neutral"}
147	        stat={formatNumber(piiReveals.length)}
148	        statLabel="PII reveals logged"
149	        title="Every contact-detail view is audited"
150	        detail={
151	          lastReveal
152	            ? `Last reveal logged ${formatTimeAgo(lastReveal)}. Each reveal writes a compliance activity with the candidate and purpose.`
153	            : "No candidate contact details have been revealed yet in this workspace."
154	        }
155	      />
156	      <Tile
157	        icon={<Ban className="h-5 w-5" aria-hidden />}
158	        tone={suppressionBreaches.length > 0 ? "danger" : "success"}
159	        stat={formatNumber(suppressionBreaches.length)}
160	        statLabel="Suppression breaches detected"
161	        title="Suppressed candidates stay suppressed"
162	        detail={`${formatNumber(activeSuppression.length)} active suppression entr${activeSuppression.length === 1 ? "y" : "ies"} and ${formatNumber(flaggedCandidates.length)} flagged candidate${flaggedCandidates.length === 1 ? "" : "s"} checked by email and domain against every outreach message still pending or scheduled to them.`}
163	      />
164	      <Tile
165	        icon={<Gauge className="h-5 w-5" aria-hidden />}
166	        tone={seatsOverCap.length > 0 ? "danger" : "success"}
167	        stat={`${formatNumber(seatsWithinCap)}/${formatNumber(seats.length)}`}
168	        statLabel="Agent seats within daily cap"
169	        title="Send-rate limits are enforced per seat"
170	        detail={
171	          seatsOverCap.length > 0
172	            ? `${seatsOverCap.length} seat${seatsOverCap.length === 1 ? "" : "s"} sent above its configured dailyLimit. Review before the next send.`
173	            : "Every agent seat's sends today are at or under its configured daily cap."
174	        }
175	      />
176	      <Tile
177	        icon={<FileLock2 className="h-5 w-5" aria-hidden />}
178	        tone={gdprExports + anonymized + doNotContact > 0 ? "success" : "neutral"}
179	        stat={formatNumber(gdprExports)}
180	        statLabel="GDPR export requests"
181	        title="Data-subject rights are tracked"
182	        detail={`${formatNumber(anonymized)} candidate${anonymized === 1 ? "" : "s"} anonymized · ${formatNumber(doNotContact)} do-not-contact flag${doNotContact === 1 ? "" : "s"} honored workspace-wide.`}
183	      />
184	    </div>
185	  );
186	}

