 7	 * Returns the raw secret string, or "" on any failure. NEVER logs or returns
 8	 * the value outside the immediate call site.
 9	 */
10	export async function resolveVaultSecret(id?: string): Promise<string> {
11	  if (!supabaseEnabled || !id) return "";
12	  const session = await getServerSupabase();
13	  const svc = getServiceSupabase();
14	  if (!session || !svc) return "";
15	  const {
16	    data: { user },
17	  } = await session.auth.getUser();
18	  if (!user) return "";
19	  const { data: wid } = await session.rpc("current_workspace_id");
20	  const { data: row } = await svc.from("api_keys").select("secret, workspace_id").eq("id", id).single();
21	  if (row && row.workspace_id === wid && typeof row.secret === "string") {
22	    return decryptSecret(row.secret);
23	  }
24	  return "";
